<script setup lang="ts">
import {computed,reactive,ref,watch,onBeforeUnmount} from 'vue';
import {isTauri} from '@tauri-apps/api/core';
import {metadata,type CatalogOption} from '../services/metadata';
import {collectionsChanged} from '../stores/collections';
type Subject={kind:string;id:string};type Row={id:string;value:Record<string,unknown>;revision:number;enabled:boolean;evidence?:{file_id:string;label:string;availability?:string}[]};
const props=defineProps<{subject:Subject;area:'source'|'license'}>();
const fields=computed(()=>props.area==='source'?[['site','사이트'],['productName','상품명'],['originalUrl','원본 URL'],['productUrl','상품 URL'],['downloadUrl','다운로드 URL'],['amount','구매 금액 (빈 값은 미확인, 0은 무료)'],['currency','통화'],['purchasedOn','구매일'],['downloadedOn','다운로드일']]:[['label','라이선스명'],['terms','이용 조건'],['attribution','출처 표시문'],['scope','적용 범위'],['note','라이선스 메모']]);
const draft=reactive<Record<string,string>>({}),rows=ref<Row[]>([]),cursor=ref<string|null>(null),recordId=ref<string|null>(null),revision=ref(0),ready=ref(false),busy=ref(false),error=ref(''),notice=ref(''),conflict=ref(false),confirmed=ref(false),reviewStatus=ref('unknown'),sourceId=ref(''),sources=ref<Row[]>([]),sourceCursor=ref<string|null>(null),files=ref<{file_id:string;label:string}[]>([]),candidates=ref<CatalogOption[]>([]),candidateLoaded=ref(false),fileCursor=ref<string|null>(null),deletePlan=ref<{references:number;expected_revision:number}>(),confirmDelete=ref(false);
let epoch=0;let baseline='';const cached=new Map<string,string>();let key='';onBeforeUnmount(()=>epoch++);
function snapshot(){return JSON.stringify({draft:{...draft},recordId:recordId.value,revision:revision.value,ready:ready.value,reviewStatus:reviewStatus.value,sourceId:sourceId.value,files:files.value});}
function restore(text:string){const s=JSON.parse(text);Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,s.draft);recordId.value=s.recordId;revision.value=s.revision;ready.value=s.ready;reviewStatus.value=s.reviewStatus;sourceId.value=s.sourceId;files.value=s.files;}
function fresh(){Object.keys(draft).forEach(k=>delete draft[k]);recordId.value=null;revision.value=0;ready.value=true;reviewStatus.value='unknown';sourceId.value='';files.value=[];for(const field of fields.value)draft[field[0]!]='';conflict.value=false;deletePlan.value=undefined;confirmed.value=false;baseline=snapshot();}
function newRecord(){if(ready.value&&snapshot()!==baseline){error.value='초안을 저장하거나 변경 취소 후 새 기록을 만드세요.';return;}fresh();}
function cancel(){if(baseline){const value=baseline;restore(value);baseline=value;}deletePlan.value=undefined;confirmed.value=false;error.value='';}
async function list(more=false){if(!isTauri()||busy.value)return;const token=epoch;busy.value=true;error.value='';try{const r=await metadata<{items:Row[];next_cursor:string|null}>(`${props.area}.list`,{subject:props.subject,after_id:more?cursor.value:null});if(token!==epoch)return;rows.value=more?[...rows.value,...r.items]:r.items;cursor.value=r.next_cursor;
 if(props.area==='license'){const s=await metadata<{items:Row[];next_cursor:string|null}>('source.list',{subject:props.subject,after_id:null});if(token===epoch){sources.value=s.items;sourceCursor.value=s.next_cursor;}}
 }catch{if(token===epoch)error.value='목록을 조회하지 못했습니다. 초안을 유지합니다.';}finally{if(token===epoch)busy.value=false;}}
async function moreSources(){if(!sourceCursor.value||busy.value)return;const token=epoch;busy.value=true;try{const r=await metadata<{items:Row[];next_cursor:string|null}>('source.list',{subject:props.subject,after_id:sourceCursor.value});if(token===epoch){sources.value=[...sources.value,...r.items];sourceCursor.value=r.next_cursor;}}catch{if(token===epoch)error.value='출처 후보를 더 조회하지 못했습니다.';}finally{if(token===epoch)busy.value=false;}}
function choose(row:Row){if(ready.value&&snapshot()!==baseline){error.value='현재 초안을 저장하거나 변경 취소 후 선택하세요.';return;}recordId.value=row.id;revision.value=row.revision;ready.value=false;deletePlan.value=undefined;error.value='';}
async function privateLoad(){if(!recordId.value||busy.value)return;const token=epoch;busy.value=true;error.value='';try{const r=await metadata<Row>(`${props.area}.get`,{record_id:recordId.value,include_private:true,confirmed:true});if(token!==epoch)return;
 for(const field of fields.value)draft[field[0]!]=String((props.area==='source'&&['amount','currency','purchasedOn','downloadedOn'].includes(field[0]!))?(r.value.purchase as Record<string,unknown>)[field[0]!]??'':r.value[field[0]!]??'');
 reviewStatus.value=String(r.value.reviewStatus??'unknown');sourceId.value=String(r.value.source_id??'');files.value=(r.evidence??[]).map(i=>({file_id:i.file_id,label:i.label}));revision.value=r.revision;ready.value=true;conflict.value=false;baseline=snapshot();
 }catch{if(token===epoch)error.value='원문을 불러오지 못했습니다. 초안을 유지합니다.';}finally{if(token===epoch)busy.value=false;}}
function value(){return props.area==='source'?{site:draft.site,productName:draft.productName,originalUrl:draft.originalUrl,productUrl:draft.productUrl,downloadUrl:draft.downloadUrl,purchase:{amount:draft.amount||null,currency:draft.currency,purchasedOn:draft.purchasedOn,downloadedOn:draft.downloadedOn}}:{label:draft.label,terms:draft.terms,attribution:draft.attribution,scope:draft.scope,note:draft.note,reviewStatus:reviewStatus.value,source_id:sourceId.value||null};}
async function save(){if(busy.value||!ready.value||conflict.value||(props.area==='license'&&!confirmed.value))return;const token=epoch;busy.value=true;error.value='';try{const update=recordId.value!==null;const r=await metadata<Row>(`${props.area}.${update?'update':'create'}`,{...(update?{record_id:recordId.value,expected_revision:revision.value}:{subject:props.subject}),value:value(),...(props.area==='license'?{confirmed:true}:{})});if(token!==epoch)return;recordId.value=r.id;revision.value=r.revision;baseline=snapshot();confirmed.value=false;notice.value='사용자 정보를 저장했습니다.';collectionsChanged();}catch(e){if(token===epoch){conflict.value=e instanceof Error&&e.message==='METADATA_CONFLICT';error.value=conflict.value?'다른 변경이 있습니다. 초안을 유지하며 다시 조회가 필요합니다.':'저장하지 못했습니다. 입력과 초안을 확인하세요.';}}finally{if(token===epoch)busy.value=false;}}
async function reviewDelete(){if(!recordId.value||busy.value)return;const token=epoch;busy.value=true;try{const r=await metadata<{references:number;expected_revision:number}>(`${props.area}.delete.preview`,{record_id:recordId.value});if(token===epoch){deletePlan.value=r;confirmDelete.value=false;}}catch{if(token===epoch)error.value='삭제 영향을 조회하지 못했습니다.';}finally{if(token===epoch)busy.value=false;}}
async function remove(){if(!recordId.value||!deletePlan.value||!confirmDelete.value||busy.value)return;const token=epoch;busy.value=true;try{await metadata(`${props.area}.delete`,{record_id:recordId.value,expected_revision:deletePlan.value.expected_revision,expected_references:deletePlan.value.references,confirmed:true});if(token!==epoch)return;fresh();notice.value='기록을 비활성화했습니다. 원본·참조·이력은 보존됩니다.';collectionsChanged();}catch{if(token===epoch)error.value='삭제 검토 이후 변경되었거나 저장에 실패했습니다. 다시 검토하세요.';}finally{if(token===epoch)busy.value=false;}}
async function loadFiles(){if(busy.value||(candidateLoaded.value&&!fileCursor.value))return;const token=epoch;busy.value=true;try{const r=await metadata<{items:CatalogOption[];next_cursor:string|null}>('catalog.evidence_candidates',{subject:props.subject,after_id:fileCursor.value});if(token===epoch){candidates.value=[...candidates.value,...r.items];fileCursor.value=r.next_cursor;candidateLoaded.value=true;}}catch{if(token===epoch)error.value='증빙 후보를 조회하지 못했습니다.';}finally{if(token===epoch)busy.value=false;}}
async function saveFiles(){if(!recordId.value||busy.value||!confirmed.value||conflict.value)return;const token=epoch;busy.value=true;try{const r=await metadata<Row>('license.evidence.save',{record_id:recordId.value,files:files.value.map(i=>({...i})),expected_revision:revision.value,confirmed:true});if(token===epoch){revision.value=r.revision;baseline=snapshot();notice.value='증빙 참조를 저장했습니다.';}}catch(e){if(token===epoch){conflict.value=e instanceof Error&&e.message==='METADATA_CONFLICT';error.value='증빙을 저장하지 못했습니다. 경로·소속·누락·버전을 확인하세요.';}}finally{if(token===epoch)busy.value=false;}}
function toggleFile(item:CatalogOption,checked:boolean){files.value=checked?[...files.value,{file_id:item.id,label:item.name}]:files.value.filter(f=>f.file_id!==item.id);}
watch(()=>`${props.subject.kind}:${props.subject.id}:${props.area}`,next=>{if(key)cached.set(key,JSON.stringify({value:snapshot(),baseline}));key=next;epoch++;busy.value=false;rows.value=[];cursor.value=null;candidates.value=[];candidateLoaded.value=false;fileCursor.value=null;sources.value=[];notice.value='';fresh();const old=cached.get(key);if(old){const saved=JSON.parse(old);restore(saved.value);baseline=saved.baseline;}void list();},{immediate:true});
</script>
<template><section :aria-label="area==='source'?'출처·구매 편집':'라이선스·증빙 편집'"><h3>{{area==='source'?'출처·상품·구매':'라이선스 선언·증빙'}}</h3>
 <button type="button" :disabled="busy" @click="list()">기록 목록 새로고침</button><button type="button" :disabled="busy" @click="newRecord">새 기록</button><button v-if="cursor" type="button" :disabled="busy" @click="list(true)">기록 더 보기</button>
 <ul><li v-for="row in rows" :key="row.id"><button type="button" :disabled="busy" @click="choose(row)">{{String(row.value.productName||row.value.label||'미확인 이름')}}</button></li></ul>
 <p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <button v-if="recordId" type="button" :disabled="busy" @click="privateLoad">민감 원문 조회 승인 · 초안 다시 불러오기</button>
 <p v-if="area==='license'">이용 허가: 미확인. 사용자 검토와 증빙 참조는 권리·호환성 검증이 아닙니다.</p>
 <form @submit.prevent="save"><fieldset :disabled="busy||!ready"><label v-for="field in fields" :key="field[0]">{{field[1]}}<textarea v-if="['terms','attribution','note'].includes(field[0]!)" v-model="draft[field[0]!]" :maxlength="field[0]==='terms'?1024:256" /><input v-else v-model="draft[field[0]!]" :type="field[0]?.endsWith('On')?'date':'text'" :maxlength="field[0]?.endsWith('Url')?512:256" /></label>
 <template v-if="area==='license'"><label>검토 상태<select v-model="reviewStatus"><option value="unknown">미확인</option><option value="needs_review">검토 필요</option><option value="user_reviewed">사용자가 검토함</option></select></label><label>연결 출처<select v-model="sourceId"><option value="">미확인</option><option v-if="sourceId&&!sources.some(s=>s.id===sourceId)" :value="sourceId">보존된 출처 {{sourceId}}</option><option v-for="s in sources" :key="s.id" :value="s.id">{{String(s.value.productName||s.value.site||s.id)}}</option></select></label><button v-if="sourceCursor" type="button" @click="moreSources">출처 후보 더 보기</button><label><input v-model="confirmed" type="checkbox" />사용자 선언·증빙 저장 승인</label></template>
 <button :disabled="conflict||(area==='license'&&!confirmed)">기록 저장</button><button type="button" @click="cancel">기록 변경 취소</button></fieldset></form>
 <section v-if="area==='license'&&recordId&&ready" aria-label="증빙 선택"><button type="button" :disabled="busy||(candidateLoaded&&!fileCursor)" @click="loadFiles">{{fileCursor?'증빙 후보 더 보기':'등록 파일에서 증빙 선택'}}</button><ul><li v-for="f in files" :key="f.file_id">{{f.label}} · {{f.file_id}}<button type="button" @click="files=files.filter(i=>i.file_id!==f.file_id)">이 증빙 참조 해제</button></li></ul><label v-for="c in candidates" :key="c.id"><input type="checkbox" :checked="files.some(f=>f.file_id===c.id)" @change="toggleFile(c,($event.target as HTMLInputElement).checked)" />{{c.name}}</label><button type="button" :disabled="busy||!confirmed||conflict" @click="saveFiles">증빙 참조 저장</button></section>
 <template v-if="recordId"><button type="button" :disabled="busy" @click="reviewDelete">삭제 영향 검토</button><div v-if="deletePlan"><p>보존되는 참조 {{deletePlan.references}}개 · 원본 파일은 변경하지 않습니다.</p><label><input v-model="confirmDelete" type="checkbox" />기록 비활성화 승인</label><button type="button" :disabled="busy||!confirmDelete" @click="remove">검토한 기록 비활성화</button><button type="button" @click="deletePlan=undefined">삭제 취소</button></div></template>
</section></template>
